#include "compress.h"
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* ---- CRC32 (poly 0xEDB88320, init/xorout 0xFFFFFFFF), matching decompress.o ---- */
static uint32_t crc_table[256];
static int crc_ready = 0;

static void crc_init(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++)
            c = (c & 1) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
        crc_table[i] = c;
    }
    crc_ready = 1;
}

static uint32_t crc32_of(const unsigned char *p, int n) {
    if (!crc_ready) crc_init();
    uint32_t c = 0xFFFFFFFFu;
    for (int i = 0; i < n; i++)
        c = crc_table[(c ^ p[i]) & 0xFFu] ^ (c >> 8);
    return ~c;
}

int compressBound(int inputSize) {
    if (inputSize < 0) return -1;
    return inputSize + inputSize / 64 + 64;
}

#define HASH_BITS 16
#define HASH_SIZE (1u << HASH_BITS)

static uint32_t hash4(const unsigned char *p) {
    uint32_t v;
    memcpy(&v, p, 4);
    return (v * 2654435761u) >> (32 - HASH_BITS);
}

static unsigned char *emit_varint(unsigned char *op, unsigned int v) {
    while (v >= 0x80) {
        *op++ = (unsigned char)((v & 0x7Fu) | 0x80u);
        v >>= 7;
    }
    *op++ = (unsigned char)v;
    return op;
}

/* Emit token + optional litlen varint + literal bytes. matchNibble is the low nibble. */
static unsigned char *emit_literals(unsigned char *op, const unsigned char *lit,
                                    int litlen, int matchNibble) {
    if (litlen < 15) {
        *op++ = (unsigned char)((litlen << 4) | matchNibble);
    } else {
        *op++ = (unsigned char)(0xF0 | matchNibble);
        op = emit_varint(op, (unsigned int)(litlen - 15));
    }
    if (litlen > 0) {
        memcpy(op, lit, (size_t)litlen);
        op += litlen;
    }
    return op;
}

int compress(const char *source, char *dest, int sourceSize) {
    const unsigned char *src = (const unsigned char *)source;
    int n = sourceSize;
    if (n < 0 || (src == NULL && n > 0) || dest == NULL) return -1;

    unsigned char *op = (unsigned char *)dest;

    /* header: magic + big-endian original size */
    *op++ = 0xD7; *op++ = 0x9C; *op++ = 0x01;
    *op++ = (unsigned char)((uint32_t)n >> 24);
    *op++ = (unsigned char)((uint32_t)n >> 16);
    *op++ = (unsigned char)((uint32_t)n >> 8);
    *op++ = (unsigned char)((uint32_t)n);

    int *table = (int *)malloc(HASH_SIZE * sizeof(int));
    if (!table) return -1;
    for (int i = 0; i < (int)HASH_SIZE; i++) table[i] = -1;

    int anchor = 0;
    int i = 0;
    while (i + 4 <= n) {
        uint32_t h = hash4(src + i);
        int cand = table[h];
        table[h] = i;
        if (cand >= 0 && i - cand <= 65535 && memcmp(src + cand, src + i, 4) == 0) {
            int mlen = 4;
            while (i + mlen < n && src[cand + mlen] == src[i + mlen]) mlen++;
            int litlen = i - anchor;
            int mnib, mext = 0;
            if (mlen <= 17) { mnib = mlen - 3; }
            else { mnib = 15; mext = mlen - 18; }
            op = emit_literals(op, src + anchor, litlen, mnib);
            int off = i - cand;
            *op++ = (unsigned char)(off >> 8);
            *op++ = (unsigned char)(off & 0xFF);
            if (mnib == 15) op = emit_varint(op, (unsigned int)mext);
            i += mlen;
            anchor = i;
        } else {
            i++;
        }
    }

    /* final literals with match nibble 0 = end of stream */
    op = emit_literals(op, src + anchor, n - anchor, 0);

    /* little-endian CRC32 trailer */
    uint32_t crc = crc32_of(src, n);
    *op++ = (unsigned char)(crc & 0xFF);
    *op++ = (unsigned char)((crc >> 8) & 0xFF);
    *op++ = (unsigned char)((crc >> 16) & 0xFF);
    *op++ = (unsigned char)((crc >> 24) & 0xFF);

    free(table);
    return (int)(op - (unsigned char *)dest);
}
